-- The schema the sync test reads. Every object is schema-qualified: the test
-- session runs as SYSTEM, which owns none of them.
CREATE USER OMNI_APP NO AUTHENTICATION QUOTA UNLIMITED ON USERS;

GRANT CREATE SESSION, CREATE TABLE, CREATE VIEW, CREATE SEQUENCE, CREATE PROCEDURE, CREATE TRIGGER, CREATE SYNONYM, CREATE MATERIALIZED VIEW TO OMNI_APP;

CREATE TABLE OMNI_APP.TYPES (
	ID NUMBER(10) NOT NULL,
	AMOUNT NUMBER(12, 2) DEFAULT 0 NOT NULL,
	ROUNDED NUMBER(5, -2),
	SCALED NUMBER(*, 2),
	RATIO FLOAT,
	LABEL VARCHAR2(50 CHAR),
	BYTES VARCHAR2(50 BYTE),
	NATIONAL NVARCHAR2(20),
	CODE CHAR(3),
	NOTE CLOB,
	BLOB_DATA BLOB,
	RAW_DATA RAW(16),
	FLAG NUMBER(1) DEFAULT 0,
	CREATED DATE DEFAULT SYSDATE,
	AT TIMESTAMP(3),
	AT_ZONE TIMESTAMP WITH TIME ZONE,
	"Mixed Case" NUMBER,
	CONSTRAINT TYPES_PK PRIMARY KEY (ID)
);

COMMENT ON TABLE OMNI_APP.TYPES IS 'types the sync reads';
COMMENT ON COLUMN OMNI_APP.TYPES.LABEL IS 'a label';
COMMENT ON COLUMN OMNI_APP.TYPES."Mixed Case" IS 'a quoted name';
COMMENT ON COLUMN OMNI_APP.TYPES.NOTE IS 'a note';

CREATE TABLE OMNI_APP.IDENT (
	ID NUMBER GENERATED ALWAYS AS IDENTITY,
	COMPUTED AS (ID * 2),
	STORED_GENERATED NUMBER GENERATED ALWAYS AS (ID + 1) VIRTUAL,
	HIDDEN NUMBER INVISIBLE DEFAULT 7,
	CONSTRAINT IDENT_PK PRIMARY KEY (ID)
);

CREATE TABLE OMNI_APP.IDENT_DEFAULT (
	ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 100 INCREMENT BY 5),
	NOTE VARCHAR2(20)
);

CREATE TABLE OMNI_APP.PARENT (
	ID NUMBER NOT NULL,
	NAME VARCHAR2(40) NOT NULL,
	CONSTRAINT PARENT_PK PRIMARY KEY (ID),
	CONSTRAINT PARENT_NAME_UK UNIQUE (NAME)
);

CREATE TABLE OMNI_APP.CHILD (
	ID NUMBER NOT NULL,
	PARENT_ID NUMBER NOT NULL,
	QTY NUMBER DEFAULT 1,
	CONSTRAINT CHILD_PK PRIMARY KEY (ID),
	CONSTRAINT CHILD_PARENT_FK FOREIGN KEY (PARENT_ID) REFERENCES OMNI_APP.PARENT (ID) ON DELETE CASCADE,
	CONSTRAINT CHILD_QTY_CK CHECK (QTY > 0)
);

CREATE INDEX OMNI_APP.CHILD_PARENT_IDX ON OMNI_APP.CHILD (PARENT_ID);

CREATE UNIQUE INDEX OMNI_APP.PARENT_UPPER_NAME_IDX ON OMNI_APP.PARENT (UPPER(NAME));

CREATE TABLE OMNI_APP.COMPOSITE (
	A NUMBER NOT NULL,
	B VARCHAR2(10) NOT NULL,
	C NUMBER,
	CONSTRAINT COMPOSITE_PK PRIMARY KEY (A, B),
	CONSTRAINT COMPOSITE_C_UK UNIQUE (C)
);

CREATE TABLE OMNI_APP.NO_CONSTRAINTS (
	A NUMBER,
	B VARCHAR2(10)
);

CREATE VIEW OMNI_APP.PARENT_VIEW AS SELECT ID, NAME FROM OMNI_APP.PARENT;

CREATE SEQUENCE OMNI_APP.ORDER_SEQ START WITH 10 INCREMENT BY 2 CACHE 20;

CREATE SYNONYM OMNI_APP.PARENT_SYN FOR OMNI_APP.PARENT;

CREATE TRIGGER OMNI_APP.PARENT_TRG BEFORE INSERT ON OMNI_APP.PARENT FOR EACH ROW BEGIN NULL; END;

CREATE MATERIALIZED VIEW OMNI_APP.PARENT_MV REFRESH COMPLETE ON DEMAND AS SELECT ID, NAME FROM OMNI_APP.PARENT;

CREATE PROCEDURE OMNI_APP.TOUCH (P_ID IN NUMBER) AS BEGIN NULL; END;
